    state.solved = true;
    const elapsed = Math.floor((Date.now() - state.startedAt) / 1000);
    const result = { completedAt: new Date().toISOString(), timeSeconds: elapsed, moves: state.moves, score: Math.max(0, 1000 - elapsed * 5 - state.moves * 10) };
    const history = loadHistory();
    history.unshift(result);
    localStorage.setItem(HISTORY_KEY, JSON.stringify(history.slice(0, 10)));
    localStorage.removeItem(STORAGE_KEY);
    hintEl.textContent = 'Success! Puzzle completed.';
    hintEl.className = 'hint good';
  }

  function saveState() {
    if (!state.solved) localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
  }

  function loadState() {
    try { return JSON.parse(localStorage.getItem(STORAGE_KEY)); } catch { return null; }
  }

  function loadHistory() {
    try { return JSON.parse(localStorage.getItem(HISTORY_KEY)) || []; } catch { return []; }
  }

  function renderHistory() {
    historyEl.innerHTML = '';
    const history = loadHistory();
    if (!history.length) { historyEl.innerHTML = '<li>No completions yet.</li>'; return; }
    history.forEach(h => {
      const li = document.createElement('li');
      li.textContent = `${h.timeSeconds}s, ${h.moves} moves, score ${h.score}`;
      historyEl.appendChild(li);
    });
  }

  resetBtn.addEventListener('click', () => {
    state = { board: initialBoard.slice(), moves: 0, startedAt: Date.now(), solved: false };
    hintEl.className = 'hint';
    render();
  });

  timer = setInterval(() => { if (!state.solved) timeEl.textContent = Math.floor((Date.now() - state.startedAt) / 1000); }, 250);
  render();
})();
</script>
</body>
</html>
